FIGSVG({"m4-abstract-structure":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 660\">\n  <defs><marker id=\"a\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"9\" markerHeight=\"9\" orient=\"auto\"><path d=\"M0 0 10 5 0 10z\" class=\"dfd\"/></marker></defs>\n  <g>\n    <rect x=\"10\" y=\"10\" width=\"580\" height=\"124\" rx=\"14\" class=\"df\"/>\n    <rect x=\"10\" y=\"10\" width=\"580\" height=\"124\" rx=\"14\" class=\"dsb\" fill=\"none\" stroke-width=\"2\"/>\n    <text x=\"30\" y=\"50\" font-size=\"28\" class=\"dtb\">1  Aim</text>\n    <text x=\"30\" y=\"86\" font-size=\"24\" class=\"dt2\">what was studied, and why</text>\n    <text x=\"30\" y=\"118\" font-size=\"22\" class=\"dt3\">\"The study aimed to investigate…\"</text>\n    <path d=\"M300 138v18\" class=\"ds2\" stroke-width=\"2.5\" marker-end=\"url(#a)\"/>\n\n    <rect x=\"10\" y=\"166\" width=\"580\" height=\"124\" rx=\"14\" class=\"df\"/>\n    <rect x=\"10\" y=\"166\" width=\"580\" height=\"124\" rx=\"14\" class=\"dso\" fill=\"none\" stroke-width=\"2\"/>\n    <text x=\"30\" y=\"206\" font-size=\"28\" class=\"dto\">2  Method</text>\n    <text x=\"30\" y=\"242\" font-size=\"24\" class=\"dt2\">who, where, when and how</text>\n    <text x=\"30\" y=\"274\" font-size=\"22\" class=\"dt3\">\"Data were collected through…\"</text>\n    <path d=\"M300 294v18\" class=\"ds2\" stroke-width=\"2.5\" marker-end=\"url(#a)\"/>\n\n    <rect x=\"10\" y=\"322\" width=\"580\" height=\"124\" rx=\"14\" class=\"df\"/>\n    <rect x=\"10\" y=\"322\" width=\"580\" height=\"124\" rx=\"14\" class=\"dsg\" fill=\"none\" stroke-width=\"2\"/>\n    <text x=\"30\" y=\"362\" font-size=\"28\" class=\"dtg\">3  Findings</text>\n    <text x=\"30\" y=\"398\" font-size=\"24\" class=\"dt2\">what the data showed (numbers)</text>\n    <text x=\"30\" y=\"430\" font-size=\"22\" class=\"dt3\">\"The findings showed that…\"</text>\n    <path d=\"M300 450v18\" class=\"ds2\" stroke-width=\"2.5\" marker-end=\"url(#a)\"/>\n\n    <rect x=\"10\" y=\"478\" width=\"580\" height=\"124\" rx=\"14\" class=\"df\"/>\n    <rect x=\"10\" y=\"478\" width=\"580\" height=\"124\" rx=\"14\" class=\"dsp\" fill=\"none\" stroke-width=\"2\"/>\n    <text x=\"30\" y=\"518\" font-size=\"28\" class=\"dtp\">4  Conclusion</text>\n    <text x=\"30\" y=\"554\" font-size=\"24\" class=\"dt2\">what the results mean</text>\n    <text x=\"30\" y=\"586\" font-size=\"22\" class=\"dt3\">\"The study concluded that…\"</text>\n\n    <text x=\"300\" y=\"644\" font-size=\"22\" text-anchor=\"middle\" class=\"dt2\">one paragraph · past tense · about 100 words</text>\n  </g>\n</svg>\n","m4-m-lr-four-tasks":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 522\">\r\n  <defs><marker id=\"a\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"9\" markerHeight=\"9\" orient=\"auto\"><path d=\"M0 0 10 5 0 10z\" class=\"dfd\"/></marker></defs>\r\n  <g>\r\n  <rect x=\"10\" y=\"10\" width=\"580\" height=\"84\" rx=\"14\" class=\"dfb\" fill-opacity=\".16\"/>\r\n  <rect x=\"10\" y=\"10\" width=\"10\" height=\"84\" rx=\"4\" class=\"dfb\"/>\r\n  <text x=\"42\" y=\"46\" font-size=\"26\" class=\"dtb\">Summarize</text>\r\n  <text x=\"42\" y=\"78\" font-size=\"22\" class=\"dt2\">Say what each source found</text>\r\n  <rect x=\"10\" y=\"106\" width=\"580\" height=\"84\" rx=\"14\" class=\"dfg\" fill-opacity=\".16\"/>\r\n  <rect x=\"10\" y=\"106\" width=\"10\" height=\"84\" rx=\"4\" class=\"dfg\"/>\r\n  <text x=\"42\" y=\"142\" font-size=\"26\" class=\"dtg\">Synthesize</text>\r\n  <text x=\"42\" y=\"174\" font-size=\"22\" class=\"dt2\">Join sources into one picture</text>\r\n  <rect x=\"10\" y=\"202\" width=\"580\" height=\"84\" rx=\"14\" class=\"dfo\" fill-opacity=\".16\"/>\r\n  <rect x=\"10\" y=\"202\" width=\"10\" height=\"84\" rx=\"4\" class=\"dfo\"/>\r\n  <text x=\"42\" y=\"238\" font-size=\"26\" class=\"dto\">Compare</text>\r\n  <text x=\"42\" y=\"270\" font-size=\"22\" class=\"dt2\">Where sources agree and differ</text>\r\n  <rect x=\"10\" y=\"298\" width=\"580\" height=\"84\" rx=\"14\" class=\"dfr\" fill-opacity=\".16\"/>\r\n  <rect x=\"10\" y=\"298\" width=\"10\" height=\"84\" rx=\"4\" class=\"dfr\"/>\r\n  <text x=\"42\" y=\"334\" font-size=\"26\" class=\"dtr\">Critique</text>\r\n  <text x=\"42\" y=\"366\" font-size=\"22\" class=\"dt2\">Judge strengths and weaknesses</text>\r\n  <path d=\"M300 390v26\" class=\"ds2\" stroke-width=\"2.5\" fill=\"none\" marker-end=\"url(#a)\"/>\r\n  <rect x=\"10\" y=\"428\" width=\"580\" height=\"84\" rx=\"14\" class=\"df2 dsy\" stroke-width=\"2.5\"/>\r\n  <text x=\"300\" y=\"464\" font-size=\"26\" text-anchor=\"middle\" class=\"dty\">An argument about the research</text>\r\n  <text x=\"300\" y=\"496\" font-size=\"22\" text-anchor=\"middle\" class=\"dt2\">never just a list of studies</text>\r\n  </g>\r\n</svg>\r\n","m4-m-lr-patterns":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 494\">\n  <g>\n  <rect x=\"10\" y=\"10\" width=\"580\" height=\"84\" rx=\"14\" class=\"dfb\" fill-opacity=\".16\"/>\n  <rect x=\"10\" y=\"10\" width=\"10\" height=\"84\" rx=\"4\" class=\"dfb\"/>\n  <text x=\"42\" y=\"46\" font-size=\"26\" class=\"dtb\">Topical</text>\n  <text x=\"42\" y=\"78\" font-size=\"22\" class=\"dt2\">Subtopics, each taken in turn</text>\n  <rect x=\"10\" y=\"106\" width=\"580\" height=\"84\" rx=\"14\" class=\"dfg\" fill-opacity=\".16\"/>\n  <rect x=\"10\" y=\"106\" width=\"10\" height=\"84\" rx=\"4\" class=\"dfg\"/>\n  <text x=\"42\" y=\"142\" font-size=\"26\" class=\"dtg\">Distant to close</text>\n  <text x=\"42\" y=\"174\" font-size=\"22\" class=\"dt2\">Loosely related first, closest work last</text>\n  <rect x=\"10\" y=\"202\" width=\"580\" height=\"84\" rx=\"14\" class=\"dfr\" fill-opacity=\".16\"/>\n  <rect x=\"10\" y=\"202\" width=\"10\" height=\"84\" rx=\"4\" class=\"dfr\"/>\n  <text x=\"42\" y=\"238\" font-size=\"26\" class=\"dtr\">Debate</text>\n  <text x=\"42\" y=\"270\" font-size=\"22\" class=\"dt2\">Camps argue; show each side</text>\n  <rect x=\"10\" y=\"298\" width=\"580\" height=\"84\" rx=\"14\" class=\"dfo\" fill-opacity=\".16\"/>\n  <rect x=\"10\" y=\"298\" width=\"10\" height=\"84\" rx=\"4\" class=\"dfo\"/>\n  <text x=\"42\" y=\"334\" font-size=\"26\" class=\"dto\">Chronological</text>\n  <text x=\"42\" y=\"366\" font-size=\"22\" class=\"dt2\">The field changed over time</text>\n  <rect x=\"10\" y=\"394\" width=\"580\" height=\"84\" rx=\"14\" class=\"dfp\" fill-opacity=\".16\"/>\n  <rect x=\"10\" y=\"394\" width=\"10\" height=\"84\" rx=\"4\" class=\"dfp\"/>\n  <text x=\"42\" y=\"430\" font-size=\"26\" class=\"dtp\">Seminal study</text>\n  <text x=\"42\" y=\"462\" font-size=\"22\" class=\"dt2\">One key study first, then the rest</text>\n  </g>\n</svg>\n","m4-m-paper-parts":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 964\">\r\n  <g>\r\n  <text x=\"14\" y=\"30\" font-size=\"24\" class=\"dt3\">Front of the paper</text>\r\n  <rect x=\"10\" y=\"44\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dsb\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"77\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"85\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">1</text>\r\n  <text x=\"82\" y=\"72\" font-size=\"25\" class=\"dt\">Title</text>\r\n  <text x=\"82\" y=\"100\" font-size=\"22\" class=\"dt2\">Fewest words that describe the paper</text>\r\n  <rect x=\"10\" y=\"120\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dsb\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"153\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"161\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">2</text>\r\n  <text x=\"82\" y=\"148\" font-size=\"25\" class=\"dt\">Authors, affiliations</text>\r\n  <text x=\"82\" y=\"176\" font-size=\"22\" class=\"dt2\">Who did it, and where from</text>\r\n  <rect x=\"10\" y=\"196\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dsb\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"229\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"237\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">3</text>\r\n  <text x=\"82\" y=\"224\" font-size=\"25\" class=\"dt\">Abstract</text>\r\n  <text x=\"82\" y=\"252\" font-size=\"22\" class=\"dt2\">The whole paper in one paragraph</text>\r\n  <text x=\"14\" y=\"298\" font-size=\"24\" class=\"dt3\">The study</text>\r\n  <rect x=\"10\" y=\"312\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dsg\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"345\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"353\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">4</text>\r\n  <text x=\"82\" y=\"340\" font-size=\"25\" class=\"dt\">Introduction</text>\r\n  <text x=\"82\" y=\"368\" font-size=\"22\" class=\"dt2\">Problem, background, aim</text>\r\n  <rect x=\"10\" y=\"388\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dsg\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"421\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"429\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">5</text>\r\n  <text x=\"82\" y=\"416\" font-size=\"25\" class=\"dt\">Materials and methods</text>\r\n  <text x=\"82\" y=\"444\" font-size=\"22\" class=\"dt2\">Enough detail to repeat it</text>\r\n  <rect x=\"10\" y=\"464\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dsg\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"497\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"505\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">6</text>\r\n  <text x=\"82\" y=\"492\" font-size=\"25\" class=\"dt\">Results</text>\r\n  <text x=\"82\" y=\"520\" font-size=\"22\" class=\"dt2\">The data, each set shown once</text>\r\n  <rect x=\"10\" y=\"540\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dsg\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"573\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"581\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">7</text>\r\n  <text x=\"82\" y=\"568\" font-size=\"25\" class=\"dt\">Discussion</text>\r\n  <text x=\"82\" y=\"596\" font-size=\"22\" class=\"dt2\">What it means, limits, errors</text>\r\n  <rect x=\"10\" y=\"616\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dsg\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"649\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"657\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">8</text>\r\n  <text x=\"82\" y=\"644\" font-size=\"25\" class=\"dt\">Conclusions</text>\r\n  <text x=\"82\" y=\"672\" font-size=\"22\" class=\"dt2\">Follow directly from the data</text>\r\n  <text x=\"14\" y=\"718\" font-size=\"24\" class=\"dt3\">Back of the paper</text>\r\n  <rect x=\"10\" y=\"732\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dso\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"765\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"773\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">9</text>\r\n  <text x=\"82\" y=\"760\" font-size=\"25\" class=\"dt\">Acknowledgements</text>\r\n  <text x=\"82\" y=\"788\" font-size=\"22\" class=\"dt2\">Thanks, help, funding</text>\r\n  <rect x=\"10\" y=\"808\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dso\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"841\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"849\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">10</text>\r\n  <text x=\"82\" y=\"836\" font-size=\"25\" class=\"dt\">List of symbols</text>\r\n  <text x=\"82\" y=\"864\" font-size=\"22\" class=\"dt2\">Nomenclature, SI units</text>\r\n  <rect x=\"10\" y=\"884\" width=\"580\" height=\"66\" rx=\"12\" class=\"df dso\" stroke-width=\"2\"/>\r\n  <circle cx=\"42\" cy=\"917\" r=\"22\" class=\"dfw\"/><text x=\"42\" y=\"925\" font-size=\"22\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">11</text>\r\n  <text x=\"82\" y=\"912\" font-size=\"25\" class=\"dt\">References</text>\r\n  <text x=\"82\" y=\"940\" font-size=\"22\" class=\"dt2\">Only sources you consulted</text>\r\n  </g>\r\n</svg>\r\n","m4-m-review-chooser":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 782\">\r\n  <g>\r\n  <text x=\"300\" y=\"34\" font-size=\"24\" text-anchor=\"middle\" class=\"dt3\">Your question points to the review type</text>\r\n  <rect x=\"10\" y=\"52\" width=\"580\" height=\"92\" rx=\"14\" class=\"df dsb\" stroke-width=\"2\"/>\r\n  <text x=\"30\" y=\"86\" font-size=\"22\" class=\"dt2\">Does X cause Y? (narrow, specific)</text>\r\n  <text x=\"30\" y=\"124\" font-size=\"26\" class=\"dtb\">→ Systematic review</text>\r\n  <rect x=\"10\" y=\"156\" width=\"580\" height=\"92\" rx=\"14\" class=\"df dsg\" stroke-width=\"2\"/>\r\n  <text x=\"30\" y=\"190\" font-size=\"22\" class=\"dt2\">What is known about a broad topic?</text>\r\n  <text x=\"30\" y=\"228\" font-size=\"26\" class=\"dtg\">→ Scoping or literature review</text>\r\n  <rect x=\"10\" y=\"260\" width=\"580\" height=\"92\" rx=\"14\" class=\"df dso\" stroke-width=\"2\"/>\r\n  <text x=\"30\" y=\"294\" font-size=\"22\" class=\"dt2\">Combine numbers from similar studies</text>\r\n  <text x=\"30\" y=\"332\" font-size=\"26\" class=\"dto\">→ Meta-analysis</text>\r\n  <rect x=\"10\" y=\"364\" width=\"580\" height=\"92\" rx=\"14\" class=\"df dsr\" stroke-width=\"2\"/>\r\n  <text x=\"30\" y=\"398\" font-size=\"22\" class=\"dt2\">A decision is needed quickly</text>\r\n  <text x=\"30\" y=\"436\" font-size=\"26\" class=\"dtr\">→ Rapid review</text>\r\n  <rect x=\"10\" y=\"468\" width=\"580\" height=\"92\" rx=\"14\" class=\"df dsp\" stroke-width=\"2\"/>\r\n  <text x=\"30\" y=\"502\" font-size=\"22\" class=\"dt2\">Many reviews already exist</text>\r\n  <text x=\"30\" y=\"540\" font-size=\"26\" class=\"dtp\">→ Umbrella review</text>\r\n  <rect x=\"10\" y=\"572\" width=\"580\" height=\"92\" rx=\"14\" class=\"df dsy\" stroke-width=\"2\"/>\r\n  <text x=\"30\" y=\"606\" font-size=\"22\" class=\"dt2\">Make sense of qualitative studies</text>\r\n  <text x=\"30\" y=\"644\" font-size=\"26\" class=\"dty\">→ Meta-synthesis</text>\r\n  <rect x=\"10\" y=\"676\" width=\"580\" height=\"92\" rx=\"14\" class=\"df ds\" stroke-width=\"2\"/>\r\n  <text x=\"30\" y=\"710\" font-size=\"22\" class=\"dt2\">Judge the literature, build a theory</text>\r\n  <text x=\"30\" y=\"748\" font-size=\"26\" class=\"dt\">→ Critical review</text>\r\n  </g>\r\n</svg>\r\n","m4-precis-steps":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 690\">\n  <defs><marker id=\"a\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"9\" markerHeight=\"9\" orient=\"auto\"><path d=\"M0 0 10 5 0 10z\" class=\"dfd\"/></marker></defs>\n  <g>\n    <rect x=\"10\" y=\"10\" width=\"580\" height=\"88\" rx=\"14\" class=\"df\"/>\n    <circle cx=\"52\" cy=\"54\" r=\"24\" class=\"dfw\"/><text x=\"52\" y=\"63\" font-size=\"24\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">1</text>\n    <text x=\"94\" y=\"48\" font-size=\"25\" class=\"dt\">Identify reader and purpose</text>\n    <text x=\"94\" y=\"82\" font-size=\"22\" class=\"dt2\">who reads it, and what for?</text>\n    <path d=\"M300 102v14\" class=\"ds2\" stroke-width=\"2.5\" marker-end=\"url(#a)\"/>\n\n    <rect x=\"10\" y=\"126\" width=\"580\" height=\"88\" rx=\"14\" class=\"df\"/>\n    <circle cx=\"52\" cy=\"170\" r=\"24\" class=\"dfw\"/><text x=\"52\" y=\"179\" font-size=\"24\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">2</text>\n    <text x=\"94\" y=\"164\" font-size=\"25\" class=\"dt\">Read the original</text>\n    <text x=\"94\" y=\"198\" font-size=\"22\" class=\"dt2\">the whole text, for its theme</text>\n    <path d=\"M300 218v14\" class=\"ds2\" stroke-width=\"2.5\" marker-end=\"url(#a)\"/>\n\n    <rect x=\"10\" y=\"242\" width=\"580\" height=\"88\" rx=\"14\" class=\"df\"/>\n    <circle cx=\"52\" cy=\"286\" r=\"24\" class=\"dfw\"/><text x=\"52\" y=\"295\" font-size=\"24\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">3</text>\n    <text x=\"94\" y=\"280\" font-size=\"25\" class=\"dt\">Underline key ideas</text>\n    <text x=\"94\" y=\"314\" font-size=\"22\" class=\"dt2\">main points and concepts, not examples</text>\n    <path d=\"M300 334v14\" class=\"ds2\" stroke-width=\"2.5\" marker-end=\"url(#a)\"/>\n\n    <rect x=\"10\" y=\"358\" width=\"580\" height=\"88\" rx=\"14\" class=\"df\"/>\n    <circle cx=\"52\" cy=\"402\" r=\"24\" class=\"dfw\"/><text x=\"52\" y=\"411\" font-size=\"24\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">4</text>\n    <text x=\"94\" y=\"396\" font-size=\"25\" class=\"dt\">Notes for each paragraph</text>\n    <text x=\"94\" y=\"430\" font-size=\"22\" class=\"dt2\">a few words each, in your own words</text>\n    <path d=\"M300 450v14\" class=\"ds2\" stroke-width=\"2.5\" marker-end=\"url(#a)\"/>\n\n    <rect x=\"10\" y=\"474\" width=\"580\" height=\"88\" rx=\"14\" class=\"df\"/>\n    <circle cx=\"52\" cy=\"518\" r=\"24\" class=\"dfw\"/><text x=\"52\" y=\"527\" font-size=\"24\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">5</text>\n    <text x=\"94\" y=\"512\" font-size=\"25\" class=\"dt\">Write the summary</text>\n    <text x=\"94\" y=\"546\" font-size=\"22\" class=\"dt2\">prose, third person, within one-third</text>\n    <path d=\"M300 566v14\" class=\"ds2\" stroke-width=\"2.5\" marker-end=\"url(#a)\"/>\n\n    <rect x=\"10\" y=\"590\" width=\"580\" height=\"88\" rx=\"14\" class=\"df\"/>\n    <circle cx=\"52\" cy=\"634\" r=\"24\" class=\"dfw\"/><text x=\"52\" y=\"643\" font-size=\"24\" text-anchor=\"middle\" class=\"mono\" style=\"fill:var(--bg)\">6</text>\n    <text x=\"94\" y=\"628\" font-size=\"25\" class=\"dt\">Review and edit</text>\n    <text x=\"94\" y=\"662\" font-size=\"22\" class=\"dt2\">ideas, accuracy, word count</text>\n  </g>\n</svg>\n","m4-summary-vs-paraphrase":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 620\">\n  <g>\n    <text x=\"20\" y=\"40\" font-size=\"25\" class=\"dt\">Original passage</text>\n    <text x=\"580\" y=\"40\" font-size=\"22\" text-anchor=\"end\" class=\"dtb\">100%</text>\n    <rect x=\"20\" y=\"54\" width=\"560\" height=\"40\" rx=\"8\" class=\"dfb\" fill-opacity=\".3\"/>\n    <rect x=\"20\" y=\"54\" width=\"560\" height=\"40\" rx=\"8\" class=\"dsb\" fill=\"none\" stroke-width=\"2\"/>\n    <path d=\"M207 48v52\" class=\"ds\" stroke-width=\"2.5\" stroke-dasharray=\"6 5\"/>\n    <text x=\"20\" y=\"126\" font-size=\"22\" class=\"dt3\">all ideas and details, author's words</text>\n\n    <text x=\"20\" y=\"180\" font-size=\"25\" class=\"dt\">Paraphrase</text>\n    <text x=\"580\" y=\"180\" font-size=\"22\" text-anchor=\"end\" class=\"dtp\">≈ same length</text>\n    <rect x=\"20\" y=\"194\" width=\"520\" height=\"40\" rx=\"8\" class=\"dfp\" fill-opacity=\".3\"/>\n    <rect x=\"20\" y=\"194\" width=\"520\" height=\"40\" rx=\"8\" class=\"dsp\" fill=\"none\" stroke-width=\"2\"/>\n    <path d=\"M207 188v52\" class=\"ds\" stroke-width=\"2.5\" stroke-dasharray=\"6 5\"/>\n    <text x=\"20\" y=\"266\" font-size=\"22\" class=\"dt3\">all ideas, new sentences, cited</text>\n\n    <text x=\"20\" y=\"320\" font-size=\"25\" class=\"dt\">Summary (précis)</text>\n    <text x=\"580\" y=\"320\" font-size=\"22\" text-anchor=\"end\" class=\"dtg\">≈ one-third</text>\n    <rect x=\"20\" y=\"334\" width=\"187\" height=\"40\" rx=\"8\" class=\"dfg\" fill-opacity=\".3\"/>\n    <rect x=\"20\" y=\"334\" width=\"187\" height=\"40\" rx=\"8\" class=\"dsg\" fill=\"none\" stroke-width=\"2\"/>\n    <path d=\"M207 328v52\" class=\"ds\" stroke-width=\"2.5\" stroke-dasharray=\"6 5\"/>\n    <text x=\"20\" y=\"406\" font-size=\"22\" class=\"dt3\">main ideas only, own words, as prose</text>\n\n    <text x=\"20\" y=\"460\" font-size=\"25\" class=\"dt\">Plagiarised version</text>\n    <text x=\"580\" y=\"460\" font-size=\"22\" text-anchor=\"end\" class=\"dtr\">same length</text>\n    <rect x=\"20\" y=\"474\" width=\"560\" height=\"40\" rx=\"8\" class=\"dfr\" fill-opacity=\".22\"/>\n    <rect x=\"20\" y=\"474\" width=\"560\" height=\"40\" rx=\"8\" class=\"dsr\" fill=\"none\" stroke-width=\"2\" stroke-dasharray=\"10 6\"/>\n    <path d=\"M207 468v52\" class=\"ds\" stroke-width=\"2.5\" stroke-dasharray=\"6 5\"/>\n    <text x=\"20\" y=\"546\" font-size=\"22\" class=\"dt3\">author's structure, swapped words, no credit</text>\n\n    <path d=\"M150 598h44\" class=\"ds\" stroke-width=\"2.5\" stroke-dasharray=\"6 5\"/>\n    <text x=\"206\" y=\"606\" font-size=\"22\" class=\"dt2\">= one-third of the original</text>\n  </g>\n</svg>\n"});
